B03.befehl:
// Bestellwert — Zähler und Nenner aggregiert,
// je Zelle des Blatts
SUM([Net Total]) / COUNT([Order Id])

// Ø Sterne — ein Wert je Rezension, deshalb AVG
AVG([Stars])

// Umsatz je Filiale (FIXED) — Level of Detail:
// die Ebene steht in der Formel, nicht im Blatt
{ FIXED [Branch Name] : SUM([Net Total]) }

// Bestellwert auf den CSV-Dateien aus notebooks/export/
// (Public Edition): je Zeile schon Summen,
// deshalb SUM durch SUM
SUM([Umsatz]) / SUM([Bestellungen])

B05.befehl:
// Parameter Jahr: Ganzzahl, 2025, Bereich 2018–2026, Schritt 1
// Ist und Vorjahr: IF innerhalb des Aggregats, kein Filter
// Umsatz Jahr · Umsatz VJ
SUM(IF YEAR([Date]) = [Jahr] THEN [Net Total] END)
SUM(IF YEAR([Date]) = [Jahr] - 1 THEN [Net Total] END)
// Bestellungen Jahr · Ø Sterne Jahr
COUNT(IF YEAR([Date]) = [Jahr] THEN [Order Id] END)
AVG(IF YEAR([Date (Fact Reviews)]) = [Jahr] THEN [Stars] END)
// Δ Umsatz % · Δ Umsatz Richtung
([Umsatz Jahr] - [Umsatz VJ]) / [Umsatz VJ]
IF [Δ Umsatz %] >= 0 THEN "plus" ELSE "minus" END
// Umsatz Tsd letzter Monat — ein Wert nur im jüngsten Monat
IF MONTH(MIN([Date])) = MONTH(MAX({ FIXED : MAX(
   IF YEAR([Date]) = [Jahr] THEN [Date] END) }))
THEN [Umsatz Tsd Jahr] END
// Titel Dashboard — STR() schreibt den Punkt, REPLACE das Komma
"Umsatz " + STR([Jahr]) + ": " + REPLACE(STR(ROUND(
  [Umsatz Jahr] / 1000000, 2)), ".", ",") + " Mio. €, "
  + IF [Δ Umsatz %] >= 0 THEN "+" ELSE "" END
  + REPLACE(STR(ROUND([Δ Umsatz %] * 100, 1)), ".", ",")
  + " % zum Vorjahr – " + MAX([Top Filiale]) + " liegt vorn"
